const body = $input.first().json.body || {};
const column = (body.projects_v2_item?.column_name || body.issue?.state || 'Ready').trim();
const issueNumber = body.issue?.number || body.projects_v2_item?.content_number || 1;
const issueTitle = body.issue?.title || body.projects_v2_item?.content_title || `Issue #${issueNumber}`;
const issueBody = body.issue?.body || 'No description';
const commentBody = body.comment?.body || '';
const sender = body.sender?.login || '';

return [{
  json: {
    column,
    issueNumber,
    issueTitle,
    issueBody,
    commentBody,
    sender,
    isHumanReply: commentBody.length > 0 && !sender.includes('[bot]')
  }
}];
